export type Plan = "free" | "pro";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  plan: Plan;
  stripeCustomerId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04", plan: "free" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11", plan: "free" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return users[0];
}

export async function getUserByStripeCustomerId(
  stripeCustomerId: string
): Promise<User | undefined> {
  return users.find((u) => u.stripeCustomerId === stripeCustomerId);
}

export async function setUserStripeCustomerId(
  id: string,
  stripeCustomerId: string
): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  if (user) user.stripeCustomerId = stripeCustomerId;
  return user;
}

export async function setUserPlan(id: string, plan: Plan): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  if (user) user.plan = plan;
  return user;
}

