import { NextRequest, NextResponse } from "next/server";
import { getStripe } from "@/lib/stripe";
import { PRO_PRICE_ID } from "@/lib/plans";
import { getCurrentUser, setUserStripeCustomerId } from "@/lib/users";

// Starts a Stripe Checkout session for the Pro monthly subscription.
// Triggered by the "Upgrade to Pro" form on /dashboard.
export async function POST(req: NextRequest) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.redirect(new URL("/dashboard", req.url), { status: 303 });
  }

  if (user.plan === "pro") {
    return NextResponse.redirect(new URL("/dashboard", req.url), { status: 303 });
  }

  if (!PRO_PRICE_ID) {
    console.error("STRIPE_PRICE_ID_PRO is not set — cannot start checkout.");
    return NextResponse.redirect(
      new URL("/dashboard?checkout=error", req.url),
      { status: 303 }
    );
  }

  try {
    const stripe = getStripe();
    const origin = req.nextUrl.origin;

    // Reuse the Stripe customer across checkout attempts instead of
    // minting a new one every time the user clicks "Upgrade".
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.name,
        metadata: { userId: user.id },
      });
      customerId = customer.id;
      await setUserStripeCustomerId(user.id, customerId);
    }

    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      customer: customerId,
      client_reference_id: user.id,
      line_items: [{ price: PRO_PRICE_ID, quantity: 1 }],
      success_url: `${origin}/dashboard?checkout=success`,
      cancel_url: `${origin}/dashboard?checkout=canceled`,
      metadata: { userId: user.id },
      subscription_data: { metadata: { userId: user.id } },
    });

    if (!session.url) {
      throw new Error("Stripe did not return a checkout URL");
    }

    return NextResponse.redirect(session.url, { status: 303 });
  } catch (err) {
    console.error("Failed to create Stripe checkout session", err);
    return NextResponse.redirect(
      new URL("/dashboard?checkout=error", req.url),
      { status: 303 }
    );
  }
}

