import { NextRequest, NextResponse } from "next/server";
import type Stripe from "stripe";
import { getStripe } from "@/lib/stripe";
import {
  getUserByStripeCustomerId,
  setUserPlan,
  setUserStripeCustomerId,
} from "@/lib/users";

function customerIdOf(customer: string | Stripe.Customer | Stripe.DeletedCustomer | null) {
  if (!customer) return undefined;
  return typeof customer === "string" ? customer : customer.id;
}

// Stripe calls this once payment succeeds (and on later subscription
// lifecycle changes). Route Handlers don't parse the body for us, so
// req.text() gives us the raw payload Stripe's signature check needs.
export async function POST(req: NextRequest) {
  const signature = req.headers.get("stripe-signature");
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!signature || !webhookSecret) {
    console.error("Stripe webhook is missing a signature or STRIPE_WEBHOOK_SECRET is unset.");
    return NextResponse.json({ error: "Webhook not configured" }, { status: 400 });
  }

  const payload = await req.text();
  const stripe = getStripe();

  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(payload, signature, webhookSecret);
  } catch (err) {
    console.error("Stripe webhook signature verification failed", err);
    return NextResponse.json({ error: "Invalid signature" }, { status: 400 });
  }

  switch (event.type) {
    // Payment for the initial subscription succeeded — flip the user to Pro.
    case "checkout.session.completed": {
      const session = event.data.object as Stripe.Checkout.Session;
      const userId = session.client_reference_id ?? session.metadata?.userId;
      const customerId = customerIdOf(session.customer);

      if (!userId) {
        console.error("checkout.session.completed had no userId on it", session.id);
        break;
      }

      if (customerId) {
        await setUserStripeCustomerId(userId, customerId);
      }
      await setUserPlan(userId, "pro");
      break;
    }

    // Subscription lapsed, was canceled, or payment failed on renewal —
    // keep the user's plan in sync with their actual subscription status.
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      const subscription = event.data.object as Stripe.Subscription;
      const customerId = customerIdOf(subscription.customer);
      if (!customerId) break;

      const user = await getUserByStripeCustomerId(customerId);
      if (!user) break;

      const isActive = subscription.status === "active" || subscription.status === "trialing";
      await setUserPlan(user.id, isActive ? "pro" : "free");
      break;
    }

    default:
      break;
  }

  return NextResponse.json({ received: true });
}

