import { getCurrentUser, listUsers } from "@/lib/users";
import { PRO_PLAN } from "@/lib/plans";

export default async function DashboardPage({
  searchParams,
}: {
  searchParams: Promise<{ checkout?: string }>;
}) {
  const { checkout } = await searchParams;
  const me = await getCurrentUser();
  const all = await listUsers();
  const isPro = me?.plan === "pro";

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      {checkout === "success" && (
        <p className="mt-4 rounded-md bg-green-50 px-4 py-2 text-sm text-green-800 dark:bg-green-950 dark:text-green-300">
          Payment received — your account will switch to Pro as soon as Stripe
          confirms the subscription (usually within a few seconds).
        </p>
      )}
      {checkout === "canceled" && (
        <p className="mt-4 rounded-md bg-amber-50 px-4 py-2 text-sm text-amber-800 dark:bg-amber-950 dark:text-amber-300">
          Checkout canceled — you&apos;re still on the Free plan.
        </p>
      )}
      {checkout === "error" && (
        <p className="mt-4 rounded-md bg-red-50 px-4 py-2 text-sm text-red-800 dark:bg-red-950 dark:text-red-300">
          Something went wrong starting checkout. Please try again.
        </p>
      )}

      <section className="mt-8 rounded-lg border border-black/10 p-4 dark:border-white/10">
        <h2 className="text-lg font-medium">Plan</h2>
        <p className="mt-1 text-sm opacity-70">
          You&apos;re currently on the{" "}
          <span className="font-medium">{isPro ? "Pro" : "Free"}</span> plan.
        </p>
        {!isPro && (
          <form action="/api/checkout" method="POST" className="mt-3">
            <button
              type="submit"
              className="rounded-full bg-foreground px-4 py-2 text-sm font-medium text-background transition-colors hover:bg-[#383838] dark:hover:bg-[#ccc]"
            >
              Upgrade to {PRO_PLAN.name} — {PRO_PLAN.priceLabel}
            </button>
          </form>
        )}
      </section>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt} —{" "}
            <span className="opacity-70">{u.plan === "pro" ? "Pro" : "Free"}</span>
          </li>
        ))}
      </ul>
    </main>
  );
}

